/**
 * 登录态持久化：H5 使用 sessionStorage（同源多标签互不覆盖）；
 * 小程序/App 仍走 uni.storage。
 */
function isH5Session(): boolean {
  try {
    return typeof window !== 'undefined' && typeof sessionStorage !== 'undefined'
  } catch {
    return false
  }
}

export function authStorageGet(key: string): string | undefined {
  try {
    if (isH5Session()) {
      const v = sessionStorage.getItem(key)
      return v != null && v !== '' ? v : undefined
    }
    const t = uni.getStorageSync(key)
    if (typeof t === 'string') return t ? t : undefined
    if (t != null && t !== '') return String(t)
    return undefined
  } catch {
    return undefined
  }
}

export function authStorageSet(key: string, value: string): void {
  try {
    if (isH5Session()) sessionStorage.setItem(key, value)
    else uni.setStorageSync(key, value)
  } catch { /* ignore quota / private mode */ }
}

export function authStorageRemove(key: string): void {
  try {
    if (isH5Session()) sessionStorage.removeItem(key)
    else uni.removeStorageSync(key)
  } catch { /* ignore */ }
}

