test('setToken/setLoginUser：两独立 storage 互不影响（模拟多标签）', () => {
  const a = new Map<string, string>()
  const b = new Map<string, string>()
  const mk = (bag: Map<string, string>) => ({
    setStorageSync: (k: string, v: unknown) => { bag.set(k, String(v)) },
    getStorageSync: (k: string) => bag.get(k) ?? '',
    removeStorageSync: (k: string) => { bag.delete(k) },
  })
  ;(globalThis as { uni: unknown }).uni = mk(a)
  setToken('token-a')
  setLoginUser({ userName: 'user-a' })
  ;(globalThis as { uni: unknown }).uni = mk(b)
  setToken('token-b')
  setLoginUser({ userName: 'user-b' })
  expect(getToken()).toBe('token-b')
  expect(getLoginUser()?.userName).toBe('user-b')
  ;(globalThis as { uni: unknown }).uni = mk(a)
  expect(getToken()).toBe('token-a')
  expect(getLoginUser()?.userName).toBe('user-a')
})
